import sysfrom PyQt5.QtWidgets import QApplicationfrom PyQt5.QtCore import QCommandLineParser, QCommandLineOptionfrom pymiri.gui import SelectData as sddef main():        app = QApplication(sys.argv)        parser = QCommandLineParser()    parser.setApplicationDescription("MIRI Data Selector")    parser.addHelpOption()    # 1. Create the Option objects correctly    # QCommandLineOption(names_list, description, valueName)    format_opt = QCommandLineOption(["f", "format"],                                     "File format to search. Default is fits.",                                     "format",                                    "fits")    kind_opt = QCommandLineOption(["t", "type"],                                   "MIRI data product type. Default is rate.",                                   "kind",                                  "rate")    # 2. Add the objects to the parser    parser.addOption(format_opt)    parser.addOption(kind_opt)        # 3. Define positional argument (the filename/path)    parser.addPositionalArgument("file", "(Optional) An input csv file. If " +                                  "the file is present then this tool will " +                                 "read the data in the file regardless of " +                                 "-f and/or -k flags.")    parser.process(app)    # Extract values    file_format = parser.value("f")    data_type = parser.value("t")        # Get positional arguments (returns a list)    pos_args = parser.positionalArguments()    input_file = pos_args[0] if pos_args else None        window = sd.MainWindow(input_file, file_format, data_type)    window.show()    sys.exit(app.exec_())